import{_ as e,o,c as d,a2 as r}from"./chunks/framework.BZO4qERu.js";const h=JSON.parse('{"title":"驱散系统","description":"","frontmatter":{},"headers":[],"relativePath":"guide/effects-dispel.md","filePath":"guide/effects-dispel.md","lastUpdated":1786203465000}'),s={name:"guide/effects-dispel.md"};function n(a,t,c,l,g,i){return o(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="驱散系统" tabindex="-1">驱散系统 <a class="header-anchor" href="#驱散系统" aria-label="Permalink to &quot;驱散系统&quot;">​</a></h1><p>特殊效果具有两种特性：<strong>驱散性</strong>和<strong>被驱散性</strong>。</p><ul><li><strong>驱散性</strong>：该特效能驱散其他特效的能力</li><li><strong>被驱散性</strong>：该特效能被哪种类型的驱散特效消除</li></ul><div class="warning custom-block"><p class="custom-block-title">关键前提</p><p>所有的驱散都只对角色<strong>状态栏</strong>上<strong>非永久性</strong>的特效起作用——<strong>装备和永久性被动提供的特效无法被驱散</strong>。</p></div><h2 id="驱散性类型-dispeltype" tabindex="-1">驱散性类型 (DispelType) <a class="header-anchor" href="#驱散性类型-dispeltype" aria-label="Permalink to &quot;驱散性类型 (DispelType)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>枚举值</th><th>中文名</th><th>能力</th></tr></thead><tbody><tr><td><code>None</code></td><td>无驱散</td><td>默认，不能驱散其他特效</td></tr><tr><td><code>Weak</code></td><td>弱驱散</td><td>消除可弱驱散的特效</td></tr><tr><td><code>DurativeWeak</code></td><td>持续性弱驱散</td><td>持续对弱驱散目标生效</td></tr><tr><td><code>TemporaryWeak</code></td><td>临时弱驱散</td><td>暂时使弱驱散可驱的特效无效化</td></tr><tr><td><code>Strong</code></td><td>强驱散</td><td>消除需强驱散和可弱驱散的特效</td></tr><tr><td><code>DurativeStrong</code></td><td>持续性强驱散</td><td>持续对强驱散目标生效</td></tr><tr><td><code>TemporaryStrong</code></td><td>临时强驱散</td><td>暂时使所有可驱散特效无效化</td></tr><tr><td><code>Special</code></td><td>特殊驱散</td><td>只对特定特效有效</td></tr></tbody></table><h3 id="驱散行为详述" tabindex="-1">驱散行为详述 <a class="header-anchor" href="#驱散行为详述" aria-label="Permalink to &quot;驱散行为详述&quot;">​</a></h3><p><strong>强驱散</strong>（较强级别的驱散类型）：</p><ul><li>对<strong>自身或友方</strong>施加强驱散：可以将<strong>所有</strong>技能施加的强控制效果和软控制效果消除；在角色状态<strong>不处于</strong>吟唱态时，直接将角色恢复为常态</li><li>对<strong>敌方</strong>施加强驱散：可以将所有<strong>需强驱散</strong>、<strong>可弱驱散</strong>的增益状态消除，<strong>不会</strong>消除其身上的负面状态</li></ul><p><strong>弱驱散</strong>（较弱级别的驱散类型）：</p><ul><li>对<strong>自身或友方</strong>施加弱驱散：可以将<strong>除了完全行动不能、行动受限、战斗不能之外</strong>的强控制效果和<strong>所有</strong>软控制效果消除；在角色状态<strong>处于</strong>技能受限和攻击受限时，将角色恢复为常态</li><li>对<strong>敌方</strong>施加弱驱散：可以将所有<strong>可弱驱散</strong>的增益状态消除，<strong>不会</strong>消除其身上的负面状态</li></ul><p><strong>临时驱散</strong>：</p><p>在下一次时间流逝前，使能够被驱散的特效<strong>暂时无效化</strong>。根据驱散强度，使能被驱散的增益状态（敌方）或者控制效果和负面状态（友方）暂时无效化。临时驱散<strong>不会</strong>将特效从角色的状态栏中移除。</p><p><strong>持续性临时驱散</strong>（简称持续性驱散）：</p><p>在一段时间内，使能够被驱散的特效无效化，在驱散的持续时间结束时<strong>恢复</strong>所有被驱散但持续时间尚未结束的特效。根据驱散强度，存在<strong>持续性强临时驱散</strong>和<strong>持续性弱临时驱散</strong>两种。</p><p><strong>特殊驱散</strong>：</p><p>特殊驱散<strong>不能</strong>消除<strong>需强驱散</strong>、也不能消除<strong>可弱驱散</strong>的特效，它只对个别特效管用，具体需要看该特效的说明。</p><p><strong>无驱散</strong>：</p><p>一般情况下特效没有驱散能力，<strong>没有标注驱散性的特效都是这个类型</strong>。而标注了驱散性的特效都将被称为<strong>驱散特效</strong>。</p><h2 id="被驱散性预设-dispelledtype" tabindex="-1">被驱散性预设 (DispelledType) <a class="header-anchor" href="#被驱散性预设-dispelledtype" aria-label="Permalink to &quot;被驱散性预设 (DispelledType)&quot;">​</a></h2><p>由 <code>SkillSet.GetDispelledTypeByEffectType()</code> 自动判定：</p><table tabindex="0"><thead><tr><th>特效类型</th><th>被驱散性</th><th>说明</th></tr></thead><tbody><tr><td><code>None</code>, <code>Item</code>, <code>Knockback</code>, <code>Unselectable</code>, <code>Doom</code></td><td><code>CannotBeDispelled</code></td><td>不可驱散</td></tr><tr><td><code>Stun</code>, <code>Freeze</code>, <code>Silence</code>, <code>Root</code>, <code>Fear</code>, <code>Sleep</code>, <code>Knockdown</code>, <code>Taunt</code>, <code>Invulnerable</code>, <code>Charm</code>, <code>Disarm</code>, <code>Confusion</code>, <code>Petrify</code>, <code>SilenceMagic</code>, <code>Banish</code></td><td><code>Strong</code></td><td>需强驱散</td></tr><tr><td>所有其他类型</td><td><code>Weak</code></td><td>可弱驱散</td></tr></tbody></table><h3 id="被驱散性详述" tabindex="-1">被驱散性详述 <a class="header-anchor" href="#被驱散性详述" aria-label="Permalink to &quot;被驱散性详述&quot;">​</a></h3><table tabindex="0"><thead><tr><th>被驱散性</th><th>说明</th></tr></thead><tbody><tr><td><strong>可弱驱散</strong></td><td>默认类型。一般情况下，<strong>没有标注被驱散性</strong>的特效都能被弱驱散所消除（上述装备和永久性特效除外）</td></tr><tr><td><strong>需强驱散</strong></td><td>需要更高级别类型的驱散。通常，具有<strong>强控制效果</strong>的特效会标注需强驱散，表示其需要此类型的驱散特效才能消除</td></tr><tr><td><strong>需特殊驱散</strong></td><td>需要<strong>特殊驱散</strong>类型的特效才能消除，具体需要看特效的说明</td></tr><tr><td><strong>不可驱散</strong></td><td>该效果<strong>无法被任何类型</strong>的驱散所消除</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">预释放爆发技与驱散</p><p><code>预释放爆发技</code> 状态自带<strong>持续性不可驱散</strong>——它并不会驱散任何强控制效果，但也不会被控制态覆盖，它的优先级永远保持最高，会<strong>一直持续</strong>直到角色完成爆发技的释放。</p><p>因此释放控制技能时，需要留意一下目标的能量条和预测目标的下一步动作，避免无效的攻击。</p></div><h2 id="驱散逻辑" tabindex="-1">驱散逻辑 <a class="header-anchor" href="#驱散逻辑" aria-label="Permalink to &quot;驱散逻辑&quot;">​</a></h2><p>在 <code>Effect.cs</code> 中的驱散实现：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>强驱散 → 能消除 DispelledType.Weak + DispelledType.Strong</span></span>
<span class="line"><span>弱驱散 → 只能消除 DispelledType.Weak（且有限制：部分强控制无法被弱驱散消除）</span></span>
<span class="line"><span>特殊驱散 → 能消除 DispelledType.Special（由具体特效决定）</span></span></code></pre></div><h2 id="驱散目标策略" tabindex="-1">驱散目标策略 <a class="header-anchor" href="#驱散目标策略" aria-label="Permalink to &quot;驱散目标策略&quot;">​</a></h2><ul><li><strong>对敌方施加强驱散</strong> → 移除所有 BUFF（<code>IsDebuff = false</code> 且可驱散的）</li><li><strong>对友方施加强驱散</strong> → 移除所有 DEBUFF + 控制状态（<code>IsDebuff = true</code> 且可驱散的），非吟唱态时恢复常态</li><li><strong>对敌方施加弱驱散</strong> → 移除可弱驱散的 BUFF</li><li><strong>对友方施加弱驱散</strong> → 移除除完全行动不能/行动受限/战斗不能外的控制效果 + 所有软控制</li></ul>`,30)])])}const u=e(s,[["render",n]]);export{h as __pageData,u as default};
